using System.Linq;using System.Collections;using NUnit.Framework;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.TestTools;using TempleDesign;
public class TempleDesignTests {
 const string Scene="Assets/Scenes/Levels/Temple.unity";
 void Load(){EditorSceneManager.OpenScene(Scene);}
 [Test]public void RequiredRoomsSignsAndDocumentsArePresent(){Load();Assert.AreEqual(6,Object.FindObjectsByType<TempleDocument>(FindObjectsSortMode.None).Length);for(int i=1;i<=6;i++){var sign=GameObject.Find("Floor_Sign_"+i);Assert.IsNotNull(sign);Assert.IsTrue(sign.GetComponent<Renderer>().sharedMaterial.mainTexture.name.StartsWith("FloorSign_0"+i));}Assert.IsNotNull(GameObject.Find("Demon_Cube_Artifact"));Assert.IsNotNull(GameObject.Find("Sacrificial_Altar_Slab"));}
 [Test]public void MainLeverIsBehindGateAndOpensItPermanently(){Load();var gate=GameObject.Find("Main_Grille_M0").GetComponent<TempleDoor>();var lever=GameObject.Find("M0").GetComponent<TempleLever>();var p=Object.FindFirstObjectByType<TemplePlayer>();Assert.Greater(lever.transform.position.z,gate.transform.position.z);Assert.IsFalse(gate.open);Assert.IsTrue(gate.locked);lever.Use(p);Assert.IsTrue(gate.open);Assert.IsFalse(gate.locked);lever.Use(p);Assert.IsTrue(gate.open);}
 [Test]public void NorthPuzzleAndInsideShortcutRespectRoute(){Load();var p=Object.FindFirstObjectByType<TemplePlayer>();var puzzle=GameObject.Find("M1").GetComponent<TemplePuzzle>();puzzle.Press(3,p);Assert.AreEqual(0,puzzle.progress);foreach(int n in new[]{1,3,2})puzzle.Press(n,p);Assert.IsTrue(puzzle.solved);Assert.IsTrue(GameObject.Find("M1_North_Passage").GetComponent<TempleDoor>().open);var door=GameObject.Find("Room_2_Inside_Shortcut").GetComponent<TempleDoor>();p.transform.position=door.transform.position+Vector3.right;door.Use(p);Assert.IsFalse(door.open);p.transform.position=door.transform.position+Vector3.left;door.Use(p);Assert.IsTrue(door.open);}
 [Test]public void SelectorTogglesBranchesWithoutChangingEscapeRoute(){Load();var p=Object.FindFirstObjectByType<TemplePlayer>();var l=GameObject.Find("МЮ").GetComponent<TempleLever>();var a=l.targets[0];var b=l.alternate;Assert.IsTrue(b.open);Assert.IsFalse(a.open);l.Use(p);Assert.IsTrue(a.open);Assert.IsFalse(b.open);l.Use(p);Assert.IsFalse(a.open);Assert.IsTrue(b.open);Assert.IsNotNull(GameObject.Find("Passages_Floor_10"));}
 [Test]public void SecretWallRequiresSixDocumentsAndCorrectSequence(){Load();var p=Object.FindFirstObjectByType<TemplePlayer>();var puzzle=GameObject.Find("Six_Signs_Secret_Wall").GetComponent<TemplePuzzle>();puzzle.Press(1,p);Assert.AreEqual(0,puzzle.progress);for(int i=1;i<=6;i++)p.documents.Add(i);puzzle.Press(2,p);Assert.IsFalse(puzzle.solved);for(int i=1;i<=6;i++)puzzle.Press(i,p);Assert.IsTrue(puzzle.solved);Assert.IsTrue(GameObject.Find("Secret_Wall_Panel").GetComponent<TempleDoor>().open);}
 [UnityTest]public IEnumerator SceneRunsAndGateActuallyMoves(){Load();yield return new EnterPlayMode();var p=Object.FindFirstObjectByType<TemplePlayer>();p.enabled=false;var gate=GameObject.Find("Main_Grille_M0").GetComponent<TempleDoor>();var panel=gate.panels[0];float y=panel.position.y;GameObject.Find("M0").GetComponent<TempleLever>().Use(p);float deadline=Time.realtimeSinceStartup+2;while(Time.realtimeSinceStartup<deadline)yield return null;Assert.Greater(panel.position.y,y+9);Assert.AreEqual(1,Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(x=>x.isActiveAndEnabled));LogAssert.NoUnexpectedReceived();yield return new ExitPlayMode();}
}
